def pancake_sort(values):
    result = list(values)

    for size in range(len(result), 1, -1):
        max_index = max(range(size), key=result.__getitem__)
        if max_index != size - 1:
            result[:max_index + 1] = reversed(result[:max_index + 1])
            result[:size] = reversed(result[:size])

    return result

