def text_match_wordz_middle(text):
    # Find all words (sequences of letters)
    words = re.findall(r'[a-z]+', text.lower())

    for word in words:
        # Check if word has 'z' not at the start or end
        # For a 'z' to be in the middle, word must have length > 2
        if len(word) > 2 and 'z' in word[1:-1]:
