def catalan_number(n):
    if n < 0:
        raise ValueError("n must be non-negative")
    result = 1
    for k in range(n):
        result = result * 2 * (2 * k + 1) // (k + 2)
    return result

def dict_depth(d):
    max_depth = 0
    for value in d.values():
        if isinstance(value, dict):
            max_depth = max(max_depth, dict_depth(value))
    return 1 + max_depth

