def find_solution(a, b, n):
    def gcd_extended(a, b):
        if b == 0:
            return a, 1, 0
        else:
            gcd, x, y = gcd_extended(b, a % b)
            return gcd, y, x - (a // b) * y

    gcd, x0, y0 = gcd_extended(a, b)

    if n % gcd != 0:
        return None

    # Scale the solution
    x0 *= n // gcd
    y0 *= n // gcd

    # Adjust x to the canonical range [0, |b/gcd|)
    b_step = b // gcd

    if b_step != 0:
        x = x0 % b_step
        y = (n - a * x) // b
    else:
        # b = 0, so the equation is a*x = n
        x = n // a
        y = y0

    return (x, y)

