def find_kth(a, b, k):
    if k < 1 or k > len(a) + len(b):
        raise ValueError("k is out of range")

    if len(a) > len(b):
        a, b = b, a

    left = max(0, k - len(b))
    right = min(k, len(a))

    while left <= right:
        cut_a = (left + right) // 2
        cut_b = k - cut_a

        a_left = a[cut_a - 1] if cut_a else float("-inf")
        a_right = a[cut_a] if cut_a < len(a) else float("inf")
        b_left = b[cut_b - 1] if cut_b else float("-inf")
        b_right = b[cut_b] if cut_b < len(b) else float("inf")

        if a_left <= b_right and b_left <= a_right:
            return max(a_left, b_left)
        if a_left > b_right:
            right = cut_a - 1
        else:
            left = cut_a + 1

    raise ValueError("Input arrays must be sorted")

def lps(s):
