    if n == 0:
        return 0

    dp = [0] * n

    for i in range(n - 1, -1, -1):
        prev = 0
        dp[i] = 1
        for j in range(i + 1, n):
            saved = dp[j]
            if s[i] == s[j]:
                dp[j] = prev + 2
            else:
                dp[j] = max(dp[j], dp[j - 1])
            prev = saved

    return dp[-1]

