def find_kth(a, b, k):
    """Return the 1-indexed kth smallest element across two sorted arrays."""
    if k < 1 or k > len(a) + len(b):
        raise ValueError("k is out of range")

    i = j = 0

    while True:
        if i == len(a):
            return b[j + k - 1]
        if j == len(b):
            return a[i + k - 1]
        if k == 1:
            return min(a[i], b[j])

        step = k // 2
        ai = min(i + step, len(a)) - 1
        bj = min(j + step, len(b)) - 1

        if a[ai] <= b[bj]:
            k -= ai - i + 1
            i = ai + 1
        else:
            k -= bj - j + 1
            j = bj + 1

