    def sum_of_proper_divisors(num):
        if num <= 1:
            return 0
        divisor_sum = 1  # 1 is always a proper divisor for num > 1
        # Check divisors up to sqrt(num)
        i = 2
        while i * i <= num:
            if num % i == 0:
                divisor_sum += i
                if i != num // i:  # Avoid counting square root twice
                    divisor_sum += num // i
            i += 1
        return divisor_sum

    amicable_set = set()
    for i in range(1, n + 1):
        sum_div = sum_of_proper_divisors(i)
        # Check if i and sum_div form an amicable pair
        if sum_div != i and sum_div <= n and sum_of_proper_divisors(sum_div) == i:
            amicable_set.add(i)

