def count_Primes_nums(n):
    if n <= 2:
        return 0

    # Create a boolean array and initialize all as prime
    prime = [True] * n
    prime[0] = prime[1] = False

    # Sieve of Eratosthenes
    p = 2
    while p * p < n:
        if prime[p]:
            # Mark all multiples of p as not prime
            for i in range(p * p, n, p):
                prime[i] = False
        p += 1

