def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    # max_increasing[i] = maximum sum of increasing subsequence ending at i
    max_increasing = [0] * n
    for i in range(n):
        max_increasing[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                max_increasing[i] = max(max_increasing[i], max_increasing[j] + arr[i])

    # max_decreasing[i] = maximum sum of decreasing subsequence starting at i
    max_decreasing = [0] * n
    for i in range(n - 1, -1, -1):
        max_decreasing[i] = arr[i]
        for j in range(i + 1, n):
            if arr[j] < arr[i]:
                max_decreasing[i] = max(max_decreasing[i], max_decreasing[j] + arr[i])

    # Find the maximum bitonic sum
    # Treat each position as a peak: increasing part before + decreasing part after
    result = 0
    for i in range(n):
        # Subtract arr[i] once since it's counted in both max_increasing and max_decreasing
        result = max(result, max_increasing[i] + max_decreasing[i] - arr[i])

    return result

def eulerian_num(n, m):
    # Initialize with the base case
    dp = {}
    dp[(0, 0)] = 1

    # Build up using the recurrence relation
    # a(n, m) = (m+1) * a(n-1, m) + (n-m) * a(n-1, m-1)
    for i in range(1, n + 1):
        for j in range(i):
            dp[(i, j)] = (j + 1) * dp.get((i-1, j), 0) + (i - j) * dp.get((i-1, j-1), 0)

    # Return the result
    return dp.get((n, m), 0)

