def max_sub_array_sum_repeated(array, n, k):
    def kadane(arr):
        max_so_far = float('-inf')
        max_ending_here = 0
        for x in arr:
            max_ending_here = max(x, max_ending_here + x)
            max_so_far = max(max_so_far, max_ending_here)
        return max_so_far

    def max_prefix_sum(arr):
        max_sum = float('-inf')
        current_sum = 0
        for x in arr:
            current_sum += x
            max_sum = max(max_sum, current_sum)
        return max_sum

    def max_suffix_sum(arr):
        max_sum = float('-inf')
        current_sum = 0
        for x in reversed(arr):
            current_sum += x
            max_sum = max(max_sum, current_sum)
        return max_sum

    if k == 1:
        return kadane(array)

    total_sum = sum(array)

    if total_sum <= 0:
        return kadane(array + array)
    else:
        max_in_one = kadane(array)
        max_prefix = max_prefix_sum(array)
        max_suffix = max_suffix_sum(array)
        return max(max_in_one, max_prefix + (k - 2) * total_sum + max_suffix)

