def heap_sort(values):
    result = list(values)
    n = len(result)

    def sift_down(start, end):
        root = start
        while True:
            child = 2 * root + 1
            if child > end:
                break
            if child + 1 <= end and result[child] < result[child + 1]:
                child += 1
            if result[root] < result[child]:
                result[root], result[child] = result[child], result[root]
                root = child
            else:
                break

    for start in range(n // 2 - 1, -1, -1):
        sift_down(start, n - 1)

    for end in range(n - 1, 0, -1):
        result[0], result[end] = result[end], result[0]
        sift_down(0, end - 1)

    return result

def shell_sort(array):
    result = list(array)
    gap = len(result) // 2

    while gap > 0:
        for i in range(gap, len(result)):
            value = result[i]
            j = i
            while j >= gap and result[j - gap] > value:
                result[j] = result[j - gap]
                j -= gap
            result[j] = value
        gap //= 2

    return result

