def find_solution(a, b, n):
    def egcd(x, y):
        if y == 0:
            return abs(x), 1 if x > 0 else -1, 0
        g, u, v = egcd(y, x % y)
        return g, v, u - (x // y) * v

    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    if a == 0:
        return (0, n // b) if n % b == 0 else None
    if b == 0:
        return (n // a, 0) if n % a == 0 else None

    g, x, y = egcd(a, b)
    if n % g != 0:
        return None

    scale = n // g
    x *= scale
    y *= scale

    step = abs(b) // g
    k = (-x) // step
    x += k * (b // g)
    y -= k * (a // g)

    return x, y

