def find_solution(a, b, n):
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    if a == 0:
        return (0, n // b) if b != 0 and n % b == 0 else None
    if b == 0:
        return (n // a, 0) if n % a == 0 else None

    d = gcd(a, b)
    if n % d != 0:
        return None

    for y in range(1, abs(n) + abs(a) + abs(b) + 1):
        remainder = n - b * y
        if remainder % a == 0:
            x = remainder // a
            if x > 0:
                return (x, y)

    return None

