def max_sum_increasing_subseq(arr, n, i, k):
    # dp[j] = maximum sum of increasing subsequence ending at index j (for j in 0 to i)
    dp = [arr[j] for j in range(i + 1)]

    # Fill DP table: for each position, find the maximum sum ending at that position
    for j in range(1, i + 1):
        for l in range(j):
            if arr[l] < arr[j]:
                dp[j] = max(dp[j], dp[l] + arr[j])

    # Find the maximum sum of increasing subsequence ending at any index in [0, i]
    # where the element at that index is less than arr[k]
    max_sum = 0
    for j in range(i + 1):
        if arr[j] < arr[k]:
            max_sum = max(max_sum, dp[j])

    # Add arr[k] to get the final answer
    return max_sum + arr[k]

