def find_kth(arr1, arr2, k):
    i, j = 0, 0

    # Advance k-1 times to position just before the kth element
    for _ in range(k - 1):
        if i < len(arr1) and (j >= len(arr2) or arr1[i] <= arr2[j]):
            i += 1
        else:
            j += 1

    # Return the smaller of the current two elements
    if i < len(arr1) and (j >= len(arr2) or arr1[i] <= arr2[j]):
        return arr1[i]
    else:
        return arr2[j]


