def eulerian_num(n, m):
    """Return the Eulerian number A(n, m): permutations of n elements with m ascents."""
    if not isinstance(n, int) or not isinstance(m, int):
        raise TypeError("n and m must be integers")
    if n < 0:
        raise ValueError("n must be non-negative")
    if m < 0 or m >= n:
        return 0
    if n == 0:
        return 1 if m == 0 else 0

    dp = [0] * n
    dp[0] = 1
    for size in range(2, n + 1):
        next_dp = [0] * n
        for ascents in range(size):
            next_dp[ascents] = (
                (ascents + 1) * dp[ascents]
                + (size - ascents) * (dp[ascents - 1] if ascents else 0)
            )
        dp = next_dp
    return dp[m]

