def magic_square_test(matrix):
    # Check if matrix is empty or not a square
    if not matrix or not matrix[0]:
        return False

    n = len(matrix)

    # Verify it's a square matrix
    for row in matrix:
        if len(row) != n:
            return False

    # Get the magic sum from the first row
    magic_sum = sum(matrix[0])

    # Check all rows
    for row in matrix:
        if sum(row) != magic_sum:
            return False

    # Check all columns
    for col in range(n):
        col_sum = sum(matrix[row][col] for row in range(n))
        if col_sum != magic_sum:
            return False

    # Check main diagonal (top-left to bottom-right)
    main_diag_sum = sum(matrix[i][i] for i in range(n))
    if main_diag_sum != magic_sum:
        return False

    # Check anti-diagonal (top-right to bottom-left)
    anti_diag_sum = sum(matrix[i][n - 1 - i] for i in range(n))
    if anti_diag_sum != magic_sum:
