    def kadane(values):
        best = current = values[0]
        for value in values[1:]:
            current = max(value, current + value)
            best = max(best, current)
        return best

    if k == 1:
        return kadane(arr)

    best_two = kadane(arr * 2)

    prefix_sum = max_prefix = arr[0]
    for value in arr[1:]:
        prefix_sum += value
        max_prefix = max(max_prefix, prefix_sum)

    suffix_sum = max_suffix = arr[-1]
    for value in reversed(arr[:-1]):
        suffix_sum += value
        max_suffix = max(max_suffix, suffix_sum)

    if total > 0:
        return max(best_two, max_suffix + max_prefix + (k - 2) * total)

