def shell_sort(arr):
    result = list(arr)
    gap = len(result) // 2

    while gap > 0:
        for i in range(gap, len(result)):
            value = result[i]
            j = i
            while j >= gap and result[j - gap] > value:
                result[j] = result[j - gap]
                j -= gap
            result[j] = value
        gap //= 2

    return result

