def get_max_sum(n):
    memo = {}

    def f(n):
        if n == 0:
            return 0
        if n == 1:
            return 1

        if n in memo:
            return memo[n]

        # Compute f(n/2) + f(n/3) + f(n/4) + f(n/5) using integer division
        sum_parts = f(n // 2) + f(n // 3) + f(n // 4) + f(n // 5)
        result = max(sum_parts, n)

        memo[n] = result
        return result

    return f(n)

