def next_smallest_palindrome(n):
    n_str = str(n + 1)
    length = len(n_str)
    is_odd = length % 2 == 1
    mid = length // 2

    def make_palindrome(left_str):
        if is_odd:
            return int(left_str + left_str[-2::-1])
        else:
            return int(left_str + left_str[::-1])

    # Try mirroring the first half of n+1
    left = n_str[:mid + 1] if is_odd else n_str[:mid]
    palin = make_palindrome(left)

    if palin > n:
        return palin

    # Increment the left part
    left_num = int(left) + 1
    left = str(left_num)

    # Check for overflow
    expected_len = mid + 1 if is_odd else mid
    if len(left) > expected_len:
        return int('1' + '0' * (length - 1) + '1')

    return make_palindrome(left)

