def cal_sum(n):
    if n < 0:
        return 0

    if n == 0:
        return 3
    elif n == 1:
        return 3
    elif n == 2:
        return 5

    # For n >= 3, generate Perrin numbers and sum them
    # Perrin sequence: P(n) = P(n-2) + P(n-3)
    # Base: P(0)=3, P(1)=0, P(2)=2
    total = 5
    a, b, c = 3, 0, 2  # P(0), P(1), P(2)

    for i in range(3, n + 1):
        d = b + a  # P(i) = P(i-2) + P(i-3)
        total += d
        a, b, c = b, c, d

    return total

