def next_smallest_palindrome(n: int) -> int:
    s = list(str(n))
    length = len(s)
    half = (length + 1) // 2

    candidate = s[:]
    candidate[length // 2:] = reversed(candidate[:half])
    value = int("".join(candidate))

    if value > n:
        return value

    prefix = str(int("".join(s[:half])) + 1)
    if len(prefix) > half:
        return int("1" + "0" * (length - 1) + "1")

    result = list(prefix)
    if length % 2 == 0:
        result += list(reversed(prefix))
    else:
        result += list(reversed(prefix[:-1]))
    return int("".join(result))

