def shell_sort(arr):
    n = len(arr)
    gap = n // 2

    while gap > 0:
        for i in range(gap, n):
            temp = arr[i]
            j = i
            while j >= gap and arr[j - gap] > temp:
                arr[j] = arr[j - gap]
                j -= gap
            arr[j] = temp
        gap //= 2

    return arr

def maxAverageOfPath(matrix):
    n = len(matrix)
    if n == 0:
        return 0.0

    dp = [[0] * n for _ in range(n)]
    dp[0][0] = matrix[0][0]

    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                continue
            best_previous = float("-inf")
            if i > 0:
                best_previous = max(best_previous, dp[i - 1][j])
            if j > 0:
                best_previous = max(best_previous, dp[i][j - 1])
            dp[i][j] = best_previous + matrix[i][j]

    return dp[-1][-1] / (2 * n - 1)

