def next_smallest_palindrome(n):
    n += 1
    s = str(n)
    length = len(s)
    is_odd = length % 2 == 1
    mid = length // 2

    # Create palindrome by mirroring first half
    if is_odd:
        left = s[:mid+1]
        palin = left + left[-2::-1]
    else:
        left = s[:mid]
        palin = left + left[::-1]

    if int(palin) >= n:
        return int(palin)

    # Increment the middle part
    left_num = int(left) + 1
    left_str = str(left_num)

    # Handle overflow
    if len(left_str) > len(left):
        return int('1' + '0' * (length - 1) + '1')

    # Create palindrome with incremented middle
    if is_odd:
        palin = left_str + left_str[-2::-1]
    else:
        palin = left_str + left_str[::-1]

    return int(palin)

