def Diff(list1, list2):
    set1 = set(list1)
    set2 = set(list2)
    diff = set1.symmetric_difference(set2)

    # If all elements of list2 are in list1, order by even/odd indices from list1
    if set2.issubset(set1):
        even_indices = []
        odd_indices = []
        for i, elem in enumerate(list1):
