def search(arr):
    left, right = 0, len(arr) - 1

    while left < right:
        mid = left + (right - left) // 2

        if mid % 2 == 0:
            # mid is even, check if arr[mid] and arr[mid+1] form a pair
            if arr[mid] == arr[mid + 1]:
                # Pair is complete, single element is to the right
                left = mid + 2
            else:
                # Pair is broken, single element is at mid or to the left
                right = mid
        else:
            # mid is odd, check if arr[mid-1] and arr[mid] form a pair
            if arr[mid - 1] == arr[mid]:
                # Pair is complete, single element is to the right
                left = mid + 1
            else:
                # Pair is broken, single element is at mid-1 or to the left
                right = mid - 1

    return arr[left]

