def sum(a, b):
    # Find GCD of the two numbers
    gcd_val = math.gcd(a, b)

    # Find all divisors of GCD and sum them
    # (common divisors of a and b are exactly the divisors of their GCD)
    divisor_sum = 0
    for i in range(1, int(math.sqrt(gcd_val)) + 1):
        if gcd_val % i == 0:
            divisor_sum += i
            if i != gcd_val // i:
                divisor_sum += gcd_val // i

    return divisor_sum

