def get_total_number_of_sequences(m, n):
    memo = {}

    def count_sequences_from(last_value, remaining_length):
        # Base case: if no more positions to fill, we have found 1 valid sequence
        if remaining_length == 0:
            return 1

        # Check memoization
        if (last_value, remaining_length) in memo:
            return memo[(last_value, remaining_length)]

        # Try all valid next values
        total = 0
        min_next_value = 2 * last_value
        for next_value in range(min_next_value, m + 1):
            total += count_sequences_from(next_value, remaining_length - 1)

        memo[(last_value, remaining_length)] = total
        return total

    # Sum sequences starting with each possible first value
    result = 0
    for first_value in range(1, m + 1):
        result += count_sequences_from(first_value, n - 1)

    return result

