def get_total_number_of_sequences(m, n):
    # dp[v] = number of sequences of current length ending with value v
    dp = [1] * (m + 1)  # dp[0] is unused; dp[1..m] = 1 for sequences of length 1

    # Build up sequences from length 2 to length n
    for _ in range(2, n + 1):
        new_dp = [0] * (m + 1)
        for v in range(1, m + 1):
            # A value u can lead to v if v >= 2 * u, i.e., u <= v // 2
            for u in range(1, v // 2 + 1):
                new_dp[v] += dp[u]
        dp = new_dp

    return sum(dp[1:])

