def find_solution(a, b, n):
    def extended_gcd(a, b):
        if b == 0:
            return a, 1, 0
        gcd, x1, y1 = extended_gcd(b, a % b)
        x = y1
        y = x1 - (a // b) * y1
        return gcd, x, y

    # Handle special cases
    if a == 0:
        if n % b == 0:
            return (0, n // b)
        else:
            return None
    if b == 0:
        if n % a == 0:
            return (n // a, 0)
        else:
            return None

    # General case: both a and b are non-zero
    a_abs = abs(a)
    b_abs = abs(b)

    d, x, y = extended_gcd(a_abs, b_abs)

    # Adjust for signs
    if a < 0:
        x = -x
    if b < 0:
        y = -y

    # Check if solution exists
    if n % d != 0:
        return None

    # Scale the solution
    factor = n // d
    x *= factor
    y *= factor

    # Canonicalize: reduce x to [0, |b/d|)
    b_step = b_abs // d
    k = x // b_step
    x -= k * b_step
    y += k * (a // d)

    return (x, y)

