def sum_of_digits(lst):
    def flatten(lst):
        result = []
        for item in lst:
            if isinstance(item, list):
                result.extend(flatten(item))
            else:
                result.append(item)
        return result

    def sum_digits_of_number(n):
        if not isinstance(n, (int, float)):
            return 0
        n = abs(int(n))
        return sum(int(d) for d in str(n))

    flattened = flatten(lst)
    return sum(sum_digits_of_number(item) for item in flattened)

def next_smallest_palindrome(n):
    s = str(n + 1)
    length = len(s)
    is_odd = length % 2 == 1
    mid = length // 2

    # Create a palindrome by mirroring the left half
    if is_odd:
        palin = s[:mid+1] + s[:mid][::-1]
    else:
        palin = s[:mid] + s[:mid][::-1]

    palin_num = int(palin)

    if palin_num >= n + 1:
        return palin_num

    # Need to increment the middle part and mirror again
    if is_odd:
        middle_part = str(int(s[:mid+1]) + 1)
        if len(middle_part) > mid + 1:
            # Overflow: need one more digit
            return int('1' + '0' * (length - 1) + '1')
        palin = middle_part + middle_part[-2::-1]
    else:
        middle_part = str(int(s[:mid]) + 1)
        if len(middle_part) > mid:
            # Overflow: need one more digit
            return int('1' + '0' * (length - 1) + '1')
        palin = middle_part + middle_part[::-1]

    return int(palin)

