def right_insertion(arr, val):
    """Find the rightmost insertion point for val in sorted array arr."""
    left, right = 0, len(arr)

    while left < right:
        mid = (left + right) // 2
        if arr[mid] <= val:
            left = mid + 1
        else:
            right = mid

    return left

