    if len(values) != len(patterns):
        return False

    value_to_pattern = {}
    pattern_to_value = {}

    for value, pattern in zip(values, patterns):
        if value_to_pattern.get(value, pattern) != pattern:
            return False
        if pattern_to_value.get(pattern, value) != value:
            return False
        value_to_pattern[value] = pattern
        pattern_to_value[pattern] = value

    return True

