def is_undulating(n):
    s = str(n)

    # Need at least 2 digits
    if len(s) < 2:
        return False

    # All even-indexed digits should match s[0]
    # All odd-indexed digits should match s[1]
    for i in range(len(s)):
        if i % 2 == 0:
            if s[i] != s[0]:
                return False
        else:
            if s[i] != s[1]:
                return False

    # Ensure s[0] != s[1] (the alternating pattern)
    return s[0] != s[1]

