def set_left_most_unset_bit(n: int) -> int:
    """Set the leftmost unset bit within n's binary representation."""
    if n <= 0:
        return n

    bit = 1 << (n.bit_length() - 1)
    while n & bit:
        bit >>= 1

    return n | bit if bit else n

