import math

def sum(a, b):
    # Find the GCD of the two numbers
    gcd = math.gcd(a, b)

    # Sum all divisors of the GCD
    divisor_sum = 0
    for i in range(1, int(math.sqrt(gcd)) + 1):
        if gcd % i == 0:
            divisor_sum += i
            if i != gcd // i:
                divisor_sum += gcd // i

    return divisor_sum

