def comb_sort(arr):
    n = len(arr)
    gap = n
    shrink = 1.3
    sorted_flag = False

    while gap > 1 or not sorted_flag:
        gap = max(1, int(gap / shrink))
        sorted_flag = True

        for i in range(n - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                sorted_flag = False

    return arr

def check_expression(expression):
    stack = []
    matching = {')': '(', '}': '{', ']': '['}

    for char in expression:
        if char in '({[':
            stack.append(char)
        elif char in ')}]':
            if not stack or stack[-1] != matching[char]:
                return False
            stack.pop()

    return len(stack) == 0

def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    # inc[i] = maximum sum of increasing subsequence ending at index i
    inc = [0] * n
    for i in range(n):
        inc[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    # dec[i] = maximum sum of decreasing subsequence starting at index i
    dec = [0] * n
    for i in range(n - 1, -1, -1):
        dec[i] = arr[i]
        for j in range(i + 1, n):
            if arr[j] < arr[i]:
                dec[i] = max(dec[i], dec[j] + arr[i])

    # Find maximum bitonic subsequence sum
    # For each potential peak at index i, calculate: inc[i] + dec[i] - arr[i]
    # (subtract arr[i] once since it's counted in both inc and dec)
    max_bitonic = 0
    for i in range(n):
        bitonic_sum = inc[i] + dec[i] - arr[i]
        max_bitonic = max(max_bitonic, bitonic_sum)

    return max_bitonic

