def get_median(a, b, n):
    i = j = 0
    previous = current = 0

    for _ in range(n + 1):
        previous = current
        if i < n and (j >= n or a[i] <= b[j]):
            current = a[i]
            i += 1
        else:
            current = b[j]
            j += 1

    return (previous + current) / 2.0

