def get_ludic(n):
    if n < 1:
        return []

    numbers = list(range(1, n + 1))
    index = 1

    while index < len(numbers):
        step = numbers[index]
        if step > len(numbers):
            break
        numbers = [
            value
            for position, value in enumerate(numbers, start=1)
            if position % step != 0
        ]
