def next_smallest_palindrome(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non-negative")

    s = list(str(n))
    length = len(s)

    mirrored = s[:]
    for i in range(length // 2):
        mirrored[-1 - i] = mirrored[i]

    candidate = int("".join(mirrored))
    if candidate > n:
        return candidate

    middle = (length - 1) // 2
    while middle >= 0 and s[middle] == "9":
        s[middle] = "0"
        middle -= 1

    if middle < 0:
        return int("1" + "0" * (length - 1) + "1")

    s[middle] = str(int(s[middle]) + 1)

    for i in range(length // 2):
        s[-1 - i] = s[i]

    return int("".join(s))

