        raise ValueError("n must be non-negative")

    bell = [0] * (n + 1)
    bell[0] = 1

    for i in range(1, n + 1):
        bell[i] = 0
        for k in range(i):
            # Binomial coefficient C(i - 1, k)
            coefficient = 1
            for j in range(k):
