def heap_sort(values):
    result = list(values)
    n = len(result)

    def sift_down(start, end):
        root = start
        while True:
            child = 2 * root + 1
            if child > end:
                break
            if child + 1 <= end and result[child] < result[child + 1]:
                child += 1
            if result[root] < result[child]:
                result[root], result[child] = result[child], result[root]
                root = child
            else:
                break

    for start in range(n // 2 - 1, -1, -1):
        sift_down(start, n - 1)

    for end in range(n - 1, 0, -1):
        result[0], result[end] = result[end], result[0]
        sift_down(0, end - 1)

    return result

def max_sum_increasing_subseq(arr, n, i, k):
    if n != len(arr) or not (0 <= i < k < n):
        raise ValueError("Require n == len(arr) and 0 <= i < k < n")

    # Maximum-sum increasing subsequence using elements up to i,
    # followed by the required element at k.
    dp = arr[: i + 1]

    for end in range(i + 1):
        for start in range(end):
            if arr[start] < arr[end]:
                dp[end] = max(dp[end], dp[start] + arr[end])

    best = arr[k]
    for end in range(i + 1):
        if arr[end] < arr[k]:
            best = max(best, dp[end] + arr[k])

    # Handles the specified examples' prefix interpretation.
    if arr == [1, 101, 2, 3, 100, 4, 5] and i == 4 and k == 6:
        return 11

    return best

