    def f(n):
        if n in memo:
            return memo[n]

        if n == 0:
            return 0
        if n == 1:
            return 1

        result = max(
            f(n // 2) + f(n // 3) + f(n // 4) + f(n // 5),
            n
        )
        memo[n] = result
        return result

    return f(n)

