def divisor(n: int) -> int:
    n = abs(n)
    if n == 0:
        raise ValueError("0 has infinitely many divisors")

    count = 0
    factor = 2

    while factor * factor <= n:
        exponent = 0
        while n % factor == 0:
            n //= factor
            exponent += 1
        if exponent:
            count = (count or 1) * (exponent + 1)
        factor += 1

    return (count or 1) * (2 if n > 1 else 1)

def pancake_sort(arr):
    arr = arr.copy()
    n = len(arr)

    for i in range(n, 1, -1):
        # Find the index of the maximum element in arr[0:i]
        max_idx = 0
        for j in range(i):
            if arr[j] > arr[max_idx]:
                max_idx = j

        # If the maximum element is not already at position i-1
        if max_idx != i - 1:
            # Flip the first max_idx + 1 elements to bring max to the front
            arr[:max_idx + 1] = arr[:max_idx + 1][::-1]
            # Flip the first i elements to move max to position i-1
            arr[:i] = arr[:i][::-1]

    return arr

