def find_first_occurrence(arr, target):
    left, right = 0, len(arr) - 1
    result = -1

    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            result = mid
            right = mid - 1  # Continue searching in the left half
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return result

def eulerian_num(n, m):
    memo = {}

    def helper(n, m):
        if (n, m) in memo:
            return memo[(n, m)]

        if n == 0:
            result = 1 if m == 0 else 0
        elif m < 0 or m >= n:
            result = 0
        else:
            result = (m + 1) * helper(n - 1, m) + (n - m) * helper(n - 1, m - 1)

        memo[(n, m)] = result
        return result

    return helper(n, m)

