def check_expression(expression):
    stack = []
    # Dictionary to map closing brackets to opening brackets
    bracket_map = {
        ')': '(',
        ']': '[',
        '}': '{'
    }

    for char in expression:
        if char in '([{':
            stack.append(char)
        elif char in ')]}':
            # Check if stack is empty
            if not stack:
                return False
            # Check if the top of the stack matches
            if stack[-1] != bracket_map[char]:
                return False
            stack.pop()

    # Stack should be empty for balanced expression
    return len(stack) == 0

