def maxAverageOfPath(matrix):
    n = len(matrix)
    if n == 0:
        return 0.0

    dp = [[0] * n for _ in range(n)]
    dp[0][0] = matrix[0][0]

    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                continue
            best_previous = float("-inf")
            if i > 0:
                best_previous = max(best_previous, dp[i - 1][j])
            if j > 0:
                best_previous = max(best_previous, dp[i][j - 1])
            dp[i][j] = best_previous + matrix[i][j]

    return dp[-1][-1] / (2 * n - 1)

def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)
    half_len = (length + 1) // 2

    prefix = int(s[:half_len])
    candidate = str(prefix) + str(prefix)[:length // 2][::-1]

    if int(candidate) <= n:
        prefix += 1
        prefix_s = str(prefix)
        if len(prefix_s) > half_len:
            return int("1" + "0" * (length - 1) + "1")
        candidate = prefix_s + prefix_s[:length // 2][::-1]

    return int(candidate)

