def lps(s: str) -> int:
    n = len(s)
    if n == 0:
        return 0

    dp = [0] * n
    for i in range(n - 1, -1, -1):
        dp[i] = 1
        diagonal = 0
        for j in range(i + 1, n):
            previous = dp[j]
            if s[i] == s[j]:
                dp[j] = diagonal + 2
            else:
                dp[j] = max(dp[j], dp[j - 1])
            diagonal = previous

    return dp[-1]

