def max_sub_array_sum_repeated(arr, n, k):
    def kadane(array):
        if not array:
            return 0
        max_sum = array[0]
        current_sum = array[0]
        for num in array[1:]:
            current_sum = max(num, current_sum + num)
            max_sum = max(max_sum, current_sum)
        return max_sum

    total_sum = sum(arr)

    # If total sum is non-positive or k == 1, max subarray is within one copy
    if total_sum <= 0 or k == 1:
        return kadane(arr)

    # If total sum is positive and k >= 2
    # Find maximum prefix sum (starting from index 0)
    max_prefix = 0
    current = 0
    for num in arr:
        current += num
        max_prefix = max(max_prefix, current)

    # Find maximum suffix sum (ending at index n-1)
    max_suffix = 0
    current = 0
    for num in reversed(arr):
        current += num
        max_suffix = max(max_suffix, current)

    # Return the maximum of: subarray within one copy, or spanning k copies
    # When spanning k copies optimally: max_suffix + (k-2)*total_sum + max_prefix
    return max(kadane(arr), max_suffix + (k - 2) * total_sum + max_prefix)

