def next_smallest_palindrome(n):
    n += 1
    s = str(n)
    length = len(s)
    is_odd = length % 2 == 1
    mid = length // 2

    # Try mirroring the left part
    if is_odd:
        left = s[:mid + 1]
        palindrome = left + left[-2::-1]
    else:
        left = s[:mid]
        palindrome = left + left[::-1]

    if int(palindrome) >= n:
        return int(palindrome)

    # Need to increment the left part
    if is_odd:
        left_num = int(s[:mid + 1]) + 1
        left = str(left_num)
        if len(left) > mid + 1:
            return 10**length + 1
        palindrome = left + left[-2::-1]
    else:
        left_num = int(s[:mid]) + 1
