        if num <= 1:
            return 0
        divisor_sum = 1
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                divisor_sum += i
                if i != num // i:
                    divisor_sum += num // i
        return divisor_sum

    amicable_sum = 0
    for num in range(1, n + 1):
        divisor_sum = sum_of_proper_divisors(num)
