def get_total_number_of_sequences(m, n):
    memo = {}

    def count(remaining_length, prev_value):
        if (remaining_length, prev_value) in memo:
            return memo[(remaining_length, prev_value)]

        # Base case: if we've placed all elements
        if remaining_length == 0:
            return 1

        # Calculate the minimum value for the next element
        if prev_value == 0:
            # First element can be 1 to m
            min_next = 1
        else:
            # Element must be >= 2 * prev_value
            min_next = 2 * prev_value

        # If min_next > m, there are no valid values
        if min_next > m:
            return 0

        # Recursive case: try all valid values for the next position
        count_sum = 0
        for next_value in range(min_next, m + 1):
            count_sum += count(remaining_length - 1, next_value)

        memo[(remaining_length, prev_value)] = count_sum
        return count_sum

    return count(n, 0)

