def eulerian_num(n, m):
    if m < 0 or m > n:
        return 0

    # Create a DP table where dp[i][j] = a(i, j)
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    # Recurrence: a(n, m) = (m+1) * a(n-1, m) + (n-m) * a(n-1, m-1)
    for i in range(1, n + 1):
        for j in range(i + 1):
            if j <= i - 1:
                dp[i][j] += (j + 1) * dp[i-1][j]
            if j > 0:
                dp[i][j] += (i - j) * dp[i-1][j-1]

    return dp[n][m]

