def find_solution(a, b, n):
    def extended_gcd(x, y):
        if y == 0:
            return abs(x), 1 if x > 0 else -1 if x < 0 else 0, 0
        g, u, v = extended_gcd(y, x % y)
        return g, v, u - (x // y) * v

    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    if a == 0:
        return (0, n // b) if b != 0 and n % b == 0 else None
    if b == 0:
        return (n // a, 0) if n % a == 0 else None

    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return None

    scale = n // g
    x0 *= scale
    y0 *= scale

    step_x = b // g
    step_y = a // g

    if step_x != 0:
        k = (-x0) % abs(step_x)
        if step_x < 0:
            k = -k
        x0 += k * step_x
        y0 -= k * step_y

    return (x0, y0)

