def max_sub_array_sum_repeated(arr, n, k):
    array_sum = sum(arr)

    def kadane(length):
        max_sum = float('-inf')
        current_sum = 0
        for i in range(length):
            current_sum += arr[i % n]
            max_sum = max(max_sum, current_sum)
            if current_sum < 0:
                current_sum = 0
        return max_sum

    # Optimization: if array sum is positive and k > 2,
    # the best subarray spans at most 2 copies, then we add (k-2) full arrays
    if array_sum > 0 and k > 2:
        max_in_two = kadane(2 * n)
        return max_in_two + (k - 2) * array_sum
    else:
        # For negative or zero sum, only need to check up to 2 copies
        copies = min(k, 2)
        return kadane(copies * n)

