def sequence(n):
    if n == 1 or n == 2:
        return 1

    # Build the sequence up to n using dynamic programming
    P = [0] * (n + 1)
    P[1] = 1
    P[2] = 1

    for i in range(3, n + 1):
        P[i] = P[P[i-1]] + P[i - P[i-1]]

    return P[n]

