def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    # Compute inc[i] = max sum of increasing subsequence ending at i
    inc = [0] * n
    inc[0] = arr[0]
    for i in range(1, n):
        inc[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], arr[i] + inc[j])

    # Compute dec[i] = max sum of decreasing subsequence starting at i
    dec = [0] * n
    dec[n-1] = arr[n-1]
    for i in range(n-2, -1, -1):
        dec[i] = arr[i]
        for j in range(i+1, n):
            if arr[j] < arr[i]:
                dec[i] = max(dec[i], arr[i] + dec[j])

    # Find maximum bitonic sum
    # For each position i as peak: inc[i] + dec[i] - arr[i]
    # (subtract arr[i] once to avoid double counting the peak)
    max_bitonic = 0
    for i in range(n):
        max_bitonic = max(max_bitonic, inc[i] + dec[i] - arr[i])

    return max_bitonic

