def amicable_numbers_sum(n):
    def sum_of_proper_divisors(num):
        if num <= 1:
            return 0
        divisor_sum = 1
        i = 2
        while i * i <= num:
            if num % i == 0:
                divisor_sum += i
                if i * i != num:
                    divisor_sum += num // i
            i += 1
        return divisor_sum

    amicable_set = set()

    for i in range(1, n + 1):
        sum_divisors = sum_of_proper_divisors(i)
        # Check if sum_divisors and i form an amicable pair
        if sum_divisors != i and sum_of_proper_divisors(sum_divisors) == i:
            amicable_set.add(i)

    return sum(amicable_set)

