def check_expression(expr):
    stack = []
    matching_pairs = {
        ')': '(',
        ']': '[',
        '}': '{'
    }

    for char in expr:
        if char in '({[':  # opening brackets
            stack.append(char)
        elif char in ')}]':  # closing brackets
            if not stack or stack[-1] != matching_pairs[char]:
                return False
            stack.pop()

    return len(stack) == 0

