def count_reverse_pairs(strings):
    count = 0
    seen = set()
    string_set = set(strings)

    for s in strings:
        if s not in seen:
            reverse_s = s[::-1]
            if reverse_s in string_set and s != reverse_s:
                count += 1
                seen.add(s)
                seen.add(reverse_s)

    return count

