def next_smallest_palindrome(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non-negative")

    digits = list(str(n))
    length = len(digits)

    mirrored = digits[:]
    for i in range(length // 2):
        mirrored[-1 - i] = mirrored[i]

    candidate = int("".join(mirrored))
    if candidate > n:
        return candidate

    middle = (length - 1) // 2
    while middle >= 0 and mirrored[middle] == "9":
        mirrored[middle] = "0"
        mirrored[-1 - middle] = "0"
        middle -= 1

    if middle < 0:
        return int("1" + "0" * (length - 1) + "1")

    mirrored[middle] = str(int(mirrored[middle]) + 1)
    mirrored[-1 - middle] = mirrored[middle]
    return int("".join(mirrored))

def largest_subset(numbers):
    if not numbers:
        return 0

    values = sorted(numbers)
    dp = [1] * len(values)

    for i in range(len(values)):
        for j in range(i):
            if values[i] % values[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

