def is_samepatterns(sequence, patterns):
    if len(sequence) != len(patterns):
        return False

    forward = {}
    backward = {}

    for value, pattern in zip(sequence, patterns):
        if value in forward and forward[value] != pattern:
            return False
        if pattern in backward and backward[pattern] != value:
            return False
        forward[value] = pattern
        backward[pattern] = value

