def is_woodall(num):
    # Woodall numbers are of the form n*2^n - 1 for positive integer n
    if num < 1:
        return False
    target = num + 1
    n = 1
    while n * (2 ** n) < target:
        n += 1
    return n * (2 ** n) == target

def reverse_vowels(s: str) -> str:
    vowels = set("aeiouAEIOU")
    chars = list(s)
    left, right = 0, len(chars) - 1

    while left < right:
        while left < right and chars[left] not in vowels:
            left += 1
        while left < right and chars[right] not in vowels:
            right -= 1
        chars[left], chars[right] = chars[right], chars[left]
        left += 1
        right -= 1

    return "".join(chars)

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    letters = test.split()

    if not letters:
        return {}

    # Count occurrences
    letter_count = {}
    for letter in letters:
        letter_count[letter] = letter_count.get(letter, 0) + 1

    # Find maximum count
    max_count = max(letter_count.values())

    # Return dictionary with letters that have max count
    result = {letter: count for letter, count in letter_count.items() if count == max_count}

    return result

def eulerian_num(n, m):
    if n < 0 or m < 0 or m >= n:
        return 0
    if n == 0:
        return 1 if m == 0 else 0

    dp = [0] * n
    dp[0] = 1

    for size in range(2, n + 1):
        next_dp = [0] * n
        for descents in range(size):
            next_dp[descents] = (
                (descents + 1) * dp[descents]
                + (size - descents) * (dp[descents - 1] if descents else 0)
            )
        dp = next_dp

    return dp[m]

def order_by_points(nums):
    """
    Write a function which sorts the given list of integers
    in ascending order according to the sum of their digits.
    Note: if there are several items with similar sum of their digits,
    order them based on their index in original list.

    For example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    >>> order_by_points([]) == []
    """
    def digit_sum(n):
        return sum(int(d) for d in str(abs(n)))

