    # Check if it's a square matrix
    for row in matrix:
        if len(row) != n:
            return False

    # Calculate the expected sum (from first row)
    expected_sum = sum(matrix[0])

    # Check all rows
    for row in matrix:
        if sum(row) != expected_sum:
            return False

    # Check all columns
    for col in range(n):
        col_sum = sum(matrix[row][col] for row in range(n))
        if col_sum != expected_sum:
            return False

    # Check main diagonal (top-left to bottom-right)
    main_diag_sum = sum(matrix[i][i] for i in range(n))
    if main_diag_sum != expected_sum:
        return False

    # Check anti-diagonal (top-right to bottom-left)
    anti_diag_sum = sum(matrix[i][n-1-i] for i in range(n))
    if anti_diag_sum != expected_sum:
        return False

    return True

def get_total_number_of_sequences(m, n):
