    for _ in range(1, n):
        suffix_sum = [0] * (m + 2)
        for value in range(m, 0, -1):
            suffix_sum[value] = suffix_sum[value + 1] + dp[value]

        dp = [0] * (m + 1)
        for value in range(1, m + 1):
            if 2 * value <= m:
                dp[value] = suffix_sum[2 * value]

    return sum(dp)

