def amicable_numbers_sum(limit):
    def divisor_sum(n):
        if n < 2:
            return 0
        total = 1
        divisor = 2
        while divisor * divisor <= n:
            if n % divisor == 0:
                total += divisor
                other = n // divisor
                if other != divisor:
                    total += other
            divisor += 1
        return total

    total = 0
    for number in range(2, limit + 1):
        partner = divisor_sum(number)
        if partner != number and partner > 0 and divisor_sum(partner) == number:
            total += number
    return total

