def next_smallest_palindrome(n):
    n += 1
    s = str(n)
    length = len(s)
    is_odd = length % 2 == 1
    mid = length // 2

    # Create palindrome by mirroring first half
    if is_odd:
        left = s[:mid+1]
        palin_str = left + left[-2::-1]
    else:
        left = s[:mid]
        palin_str = left + left[::-1]

    palin = int(palin_str)

    if palin >= n:
        return palin

    # Need to increment the middle part
    if is_odd:
        left_num = int(s[:mid+1]) + 1
        left_str = str(left_num)

        if len(left_str) > mid + 1:
            return int('1' + '0' * (length - 1) + '1')

        palin_str = left_str + left_str[-2::-1]
    else:
        left_num = int(s[:mid]) + 1
        left_str = str(left_num)

        if len(left_str) > mid:
            return int('1' + '0' * (length - 1) + '1')

        palin_str = left_str + left_str[::-1]

    return int(palin_str)

