def lps(s):
    # Remove spaces from the string
    s = s.replace(" ", "")
    n = len(s)

    if n == 0:
        return 0
    if n == 1:
        return 1

    # dp[i][j] represents the length of the longest palindromic subsequence
    # in the substring s[i:j+1]
    dp = [[0] * n for _ in range(n)]

    # Base case: single characters are palindromes of length 1
    for i in range(n):
        dp[i][i] = 1

    # Fill the DP table for substrings of increasing length
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                # If characters match, add 2 to the result of inner substring
                if length == 2:
                    dp[i][j] = 2
                else:
                    dp[i][j] = dp[i+1][j-1] + 2
            else:
                # If characters don't match, take max of excluding either end
                dp[i][j] = max(dp[i+1][j], dp[i][j-1])

    return dp[0][n-1]

def bell_number(n):
    if n < 0:
        raise ValueError("n must be non-negative")

    row = [1]
    for _ in range(n):
        next_row = [row[-1]]
        for value in row:
            next_row.append(next_row[-1] + value)
        row = next_row

    return row[0]

def get_total_number_of_sequences(m, n):
    # dp[i][v] = number of sequences of length i ending with value v
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: sequences of length 1
    for v in range(1, m + 1):
        dp[1][v] = 1

    # Fill the dp table
    for i in range(2, n + 1):
        for v in range(1, m + 1):
            # Sum contributions from previous values u where 2*u <= v
            for u in range(1, v // 2 + 1):
                dp[i][v] += dp[i-1][u]

    # Sum all sequences of length n
    return sum(dp[n][v] for v in range(1, m + 1))

