def find_kth(arr1, arr2, k):
    """Return the 1-indexed kth smallest element of two sorted arrays."""
    if k < 1 or k > len(arr1) + len(arr2):
        raise ValueError("k is out of range")

    i = j = 0

    while True:
        if i == len(arr1):
            return arr2[j + k - 1]
        if j == len(arr2):
            return arr1[i + k - 1]
        if k == 1:
            return min(arr1[i], arr2[j])

        step = k // 2
        new_i = min(i + step, len(arr1)) - 1
        new_j = min(j + step, len(arr2)) - 1

        if arr1[new_i] <= arr2[new_j]:
            k -= new_i - i + 1
            i = new_i + 1
        else:
            k -= new_j - j + 1
            j = new_j + 1

