def heap_sort(arr):
    arr = arr.copy()

    def heapify(arr, n, i):
        largest = i
        left = 2 * i + 1
        right = 2 * i + 2

        if left < n and arr[left] > arr[largest]:
            largest = left
        if right < n and arr[right] > arr[largest]:
            largest = right

        if largest != i:
            arr[i], arr[largest] = arr[largest], arr[i]
            heapify(arr, n, largest)

    n = len(arr)

    # Build max heap
    for i in range(n // 2 - 1, -1, -1):
        heapify(arr, n, i)

    # Extract elements from heap
    for i in range(n - 1, 0, -1):
        arr[0], arr[i] = arr[i], arr[0]
        heapify(arr, i, 0)

    return arr

def left_insertion(values, target):
    """Return the leftmost index where target can be inserted in sorted values."""
    low, high = 0, len(values)

    while low < high:
        mid = (low + high) // 2
        if values[mid] < target:
            low = mid + 1
        else:
            high = mid

    return low

def odd_Equivalent(binary_string, rotations):
    count = 0
    n = len(binary_string)

    for k in range(rotations):
        # After k+1 left rotations, the last digit is the character
        # originally at position k (mod n)
        # A binary number is odd iff its last digit is '1'
        if binary_string[k % n] == '1':
            count += 1

    return count

