    def flip(end):
        result[:end] = reversed(result[:end])

    for size in range(len(result), 1, -1):
        max_index = max(range(size), key=result.__getitem__)
        if max_index == size - 1:
            continue
        if max_index != 0:
            flip(max_index + 1)
        flip(size)

    return result

