def shell_sort(array):
    result = list(array)
    gap = len(result) // 2

    while gap > 0:
        for i in range(gap, len(result)):
            current = result[i]
            j = i
            while j >= gap and result[j - gap] > current:
                result[j] = result[j - gap]
                j -= gap
            result[j] = current
        gap //= 2

    return result

