    for i in range(n):
        for j in range(i):
            # If sorted_nums[j] divides sorted_nums[i]
            if sorted_nums[i] % sorted_nums[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

