def bell_number(n):
    # Create a table to store Stirling numbers of the second kind
    S = [[0] * (n + 1) for _ in range(n + 1)]

    # Base case: S(0, 0) = 1
    S[0][0] = 1

    # Fill the table using the recurrence relation
    # S(n, k) = k * S(n-1, k) + S(n-1, k-1)
    for i in range(1, n + 1):
        for j in range(1, i + 1):
            S[i][j] = j * S[i-1][j] + S[i-1][j-1]

    # The Bell number B(n) is the sum of S(n, k) for k = 0 to n
    return sum(S[n])

