def maxAverageOfPath(matrix: List[List[float]]) -> float:
    n = len(matrix)
    if n == 0:
        return 0.0

    dp = [[0.0] * n for _ in range(n)]
    dp[0][0] = matrix[0][0]

    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                continue
            best_previous = float("-inf")
            if i > 0:
                best_previous = max(best_previous, dp[i - 1][j])
            if j > 0:
                best_previous = max(best_previous, dp[i][j - 1])
            dp[i][j] = best_previous + matrix[i][j]

    return dp[n - 1][n - 1] / (2 * n - 1)

