def amicable_numbers_sum(n):
    def sum_of_proper_divisors(num):
        if num <= 1:
            return 0
        divisor_sum = 1  # 1 is always a proper divisor for num > 1
        # Check divisors up to sqrt(num)
        i = 2
        while i * i <= num:
            if num % i == 0:
                divisor_sum += i
                if i * i != num:  # Avoid adding the square root twice
                    divisor_sum += num // i
            i += 1
        return divisor_sum

    amicable_sum = 0
    for i in range(1, n + 1):
        s_i = sum_of_proper_divisors(i)
        # i is amicable if sum_of_proper_divisors(sum_of_proper_divisors(i)) == i
        # and i != sum_of_proper_divisors(i) (to exclude perfect numbers)
        if s_i != i and sum_of_proper_divisors(s_i) == i:
            amicable_sum += i

    return amicable_sum

