def max_sum_increasing_subseq(arr, n, i, k):
    target_elem = arr[k]

    # dp[j] = maximum sum of increasing subsequence ending at arr[j]
    # where all elements are strictly less than target_elem
    dp = [0] * (i + 1)

    for j in range(i + 1):
        if arr[j] < target_elem:
            dp[j] = arr[j]
            for p in range(j):
                if arr[p] < arr[j] and arr[p] < target_elem:
                    dp[j] = max(dp[j], dp[p] + arr[j])
        else:
            dp[j] = 0

    max_sum = max(dp)
    return max_sum + target_elem

