def is_nested(string):
    '''
    Create a function that takes a string as input which contains only square brackets.
    The function should return True if and only if there is a valid subsequence of brackets 
    where at least one bracket in the subsequence is nested.

    is_nested('[[]]') ➞ True
    is_nested('[]]]]]]][[[[[]') ➞ False
    is_nested('[][]') ➞ False
    is_nested('[]') ➞ False
    is_nested('[[][]]') ➞ True
    is_nested('[[]][[') ➞ True
    '''
    n = len(string)

    # Look for a subsequence with pattern: [ [ ] ]
    # This represents the simplest nested bracket structure
    # If any such pattern exists, we have valid nesting
    for i in range(n):
        if string[i] == '[':
            for j in range(i + 1, n):
                if string[j] == '[':
                    for k in range(j + 1, n):
                        if string[k] == ']':
                            for l in range(k + 1, n):
                                if string[l] == ']':
                                    return True
    return False

