def max_sub_array_sum_repeated(arr, n, k):
    arr = arr[:n]

    if not arr or k <= 0:
        return 0

    current = best = arr[0]
    for value in arr[1:] * min(k, 2):
        current = max(value, current + value)
        best = max(best, current)

    total = sum(arr)
    if k > 2 and total > 0:
        best += (k - 2) * total

    return best

